flowController.reportingTasks:
{{- if .Values.metrics.prometheus.enabled }}
{{ default uuidv4 }} PrometheusReportingTask BDP fork: metrics.prometheus.enabled only opens the port/Service (templates/statefulset.yaml, templates/service.yaml) -- NiFi never starts a listener on it unless a PrometheusReportingTask is actually defined and RUNNING. Verified against org.apache.nifi.reporting.prometheus.PrometheusReportingTask (nifi-prometheus-nar, bundled with core NiFi) at nifi 1.23.2. org.apache.nifi.reporting.prometheus.PrometheusReportingTask
org.apache.nifi nifi-prometheus-nar {{ .Chart.AppVersion }}
60 sec RUNNING TIMER_DRIVEN
prometheus-reporting-task-metrics-endpoint-port {{ .Values.metrics.prometheus.port }}
prometheus-reporting-task-metrics-strategy All Components
prometheus-reporting-task-metrics-send-jvm true
prometheus-reporting-task-client-auth No Authentication
{{- end }}
